import{_ as e,o as d,c as o,a2 as s}from"./chunks/framework.mRCPFc5l.js";const b=JSON.parse('{"title":"架构总览：一台由插件组装起来的机器","description":"","frontmatter":{},"headers":[],"relativePath":"guide/architecture.md","filePath":"guide/architecture.md","lastUpdated":null}'),a={name:"guide/architecture.md"};function c(n,t,r,l,i,p){return d(),o("div",null,[...t[0]||(t[0]=[s(`<h1 id="架构总览-一台由插件组装起来的机器" tabindex="-1">架构总览：一台由插件组装起来的机器 <a class="header-anchor" href="#架构总览-一台由插件组装起来的机器" aria-label="Permalink to &quot;架构总览：一台由插件组装起来的机器&quot;">​</a></h1><p>这篇文章把 DSH 的静态结构讲清楚：运行中的 dsh 如何被组装出来、核心包有哪些、事件如何流动、能力如何分层。读完你应该能画出完整的架构图。</p><h2 id="_1-启动-一棵插件树的诞生" tabindex="-1">1. 启动：一棵插件树的诞生 <a class="header-anchor" href="#_1-启动-一棵插件树的诞生" aria-label="Permalink to &quot;1. 启动：一棵插件树的诞生&quot;">​</a></h2><p>运行中的 <code>dsh</code> 是一棵<strong>插件树</strong>，由启动时按序叠加的各层组合而成：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>空条目列表</span></span>
<span class="line"><span>  ├─ 按 profile 顺序应用每个组合包（bundle）      ← dsh-base 永远第一层</span></span>
<span class="line"><span>  ├─ profile 自己的 cordis.patch.yml</span></span>
<span class="line"><span>  ├─ home 级的 cordis.patch.yml</span></span>
<span class="line"><span>  └─ --patch overlay（命令行覆盖）</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><p>两个关键概念：</p><ul><li><strong>profile</strong>：存放在 Harness home 的具名组装。列出自己叠放的组合包、存放树外插件、保存用户的 <code>cordis.patch.yml</code>。<code>web</code> 和 <code>headless</code> 作为模板随发行版交付。</li><li><strong>组合包（bundle）</strong>：Cordis 配置项及其挂载代码的分发格式。它插入的内容<strong>始终可被其上各层 patch</strong>——这就是&quot;没有特权内核&quot;的结构保证。</li></ul><p>内置组合包分工：</p><table tabindex="0"><thead><tr><th>组合包</th><th>内容</th></tr></thead><tbody><tr><td><code>dsh-base</code></td><td>模型适配器、工具、持久化、沙箱与审批策略、设置、凭据、遥测 —— <strong>每个 profile 的第一层</strong></td></tr><tr><td><code>dsh-web-app</code></td><td>浏览器应用（Web GUI）</td></tr><tr><td><code>dsh-headless</code></td><td>一次性运行器，<strong>完全不带服务器</strong></td></tr></tbody></table><p>查看你的机器实际启动的配置树：</p><div class="language-sh vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">dsh</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --profile</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> web</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --dump-config</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>打印出的任何条目都可以由你自己的 patch 替换——这就是配置即组装。</p><h2 id="_2-核心包-产品的-api-脊柱" tabindex="-1">2. 核心包：产品的 API 脊柱 <a class="header-anchor" href="#_2-核心包-产品的-api-脊柱" aria-label="Permalink to &quot;2. 核心包：产品的 API 脊柱&quot;">​</a></h2><p>以下包定义 DSH 的骨架（<code>docs/architecture.md</code> 官方表格）：</p><table tabindex="0"><thead><tr><th>包</th><th>职责</th><th><code>ctx</code> 键</th></tr></thead><tbody><tr><td><code>core/session</code></td><td>仅追加的 <code>SessionEvent</code> 日志和内存存储</td><td><code>ctx.sessions</code></td></tr><tr><td><code>core/system-prompt</code></td><td>提示词片段与工具 schema 的组装</td><td><code>ctx.systemPrompt</code></td></tr><tr><td><code>core/tools</code></td><td>作用域化工具注册表 + 带把关的执行流水线</td><td><code>ctx.tools</code></td></tr><tr><td><code>core/agent</code></td><td><code>Agent</code> 接口、活跃 agent 注册表、<code>agent/*</code> 事件</td><td><code>ctx.agents</code></td></tr><tr><td><code>core/agent-loop</code></td><td>实现该接口的<strong>默认驱动器</strong>（唯一具体循环插件）</td><td><code>ctx.agentLoop</code></td></tr><tr><td><code>core/scope</code></td><td>按 agent 划分作用域的注册原语</td><td>库，无 ctx 键</td></tr><tr><td><code>llm/llm</code></td><td>消息与流式词汇表、适配器 seam</td><td><code>ctx.llm</code></td></tr></tbody></table><p>注意 <code>agent-loop</code> 的定位：它只是<strong>默认实现</strong>。扩展包依赖 <code>dsh-agent</code> 的事件和服务，而不依赖此包——理论上整条循环都可以被替换。</p><h2 id="_3-服务地图-40-服务的全景" tabindex="-1">3. 服务地图：40+ 服务的全景 <a class="header-anchor" href="#_3-服务地图-40-服务的全景" aria-label="Permalink to &quot;3. 服务地图：40+ 服务的全景&quot;">​</a></h2><p>官方 <code>capability-seams</code> 文档给出了完整注册图。按领域归类（<code>ctx</code> 键 → 所属包 → 提供方实现）：</p><h3 id="模型与流式" tabindex="-1">模型与流式 <a class="header-anchor" href="#模型与流式" aria-label="Permalink to &quot;模型与流式&quot;">​</a></h3><table tabindex="0"><thead><tr><th>服务</th><th>定义包</th><th>提供方实现</th></tr></thead><tbody><tr><td><code>ctx.llm</code></td><td><code>llm</code></td><td><code>llm-deepseek</code>、<code>llm-pi-ai</code>、<code>llm-replay</code>（测试回放）</td></tr><tr><td><code>ctx.tokenMeter</code></td><td><code>token-meter</code></td><td>—（按会话隔离的回放折叠区）</td></tr><tr><td><code>ctx.toolResultPruner</code></td><td><code>compaction-tool-result-pruner</code></td><td>—</td></tr><tr><td><code>ctx.agentDefaultModel</code></td><td><code>agent-default-model</code></td><td>—</td></tr></tbody></table><h3 id="会话与存储" tabindex="-1">会话与存储 <a class="header-anchor" href="#会话与存储" aria-label="Permalink to &quot;会话与存储&quot;">​</a></h3><table tabindex="0"><thead><tr><th>服务</th><th>定义包</th><th>提供方实现</th></tr></thead><tbody><tr><td><code>ctx.sessions</code></td><td><code>session</code></td><td>—（内存，唯一）</td></tr><tr><td><code>ctx.sessionPersistence</code></td><td><code>session-persistence</code></td><td><code>-jsonl</code>、<code>-sqlite</code></td></tr><tr><td><code>ctx.sessionQuery</code></td><td><code>session-query</code></td><td><code>-sqlite</code></td></tr><tr><td><code>ctx.sessionProjections</code></td><td><code>session-projection</code></td><td>—（状态折叠单元）</td></tr><tr><td><code>ctx.sessionTitle</code></td><td><code>session-title</code></td><td><code>-first-prompt-llm</code>、<code>-all-prompts-llm</code></td></tr><tr><td><code>ctx.sessionTelemetry</code></td><td><code>session-telemetry</code></td><td><code>-otel</code>（输出离进程）</td></tr><tr><td><code>ctx.storage</code></td><td><code>storage</code></td><td><code>storage-json</code>、<code>storage-sqlite</code></td></tr><tr><td><code>ctx.workspaceRegistry</code></td><td><code>workspace</code></td><td>—</td></tr></tbody></table><h3 id="执行世界-共享同一个-执行世界-的三个-seam" tabindex="-1">执行世界（共享同一个&quot;执行世界&quot;的三个 seam） <a class="header-anchor" href="#执行世界-共享同一个-执行世界-的三个-seam" aria-label="Permalink to &quot;执行世界（共享同一个&quot;执行世界&quot;的三个 seam）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>服务</th><th>定义包</th><th>提供方实现</th></tr></thead><tbody><tr><td><code>ctx.subprocess</code></td><td><code>subprocess</code></td><td><code>subprocess-local</code>、<code>subprocess-e2b</code></td></tr><tr><td><code>ctx.shell</code></td><td><code>shell</code></td><td><code>bash-local</code>、<code>bash-sandbox</code>、<code>pwsh-local</code></td></tr><tr><td><code>ctx.terminals</code></td><td><code>terminal</code></td><td><code>terminal-bash</code>（持久 PTY）</td></tr><tr><td><code>ctx.fs</code></td><td><code>fs</code></td><td><code>fs-local</code>、<code>fs-sandbox</code>、<code>fs-e2b</code></td></tr><tr><td><code>ctx.sandbox</code></td><td><code>sandbox</code></td><td><code>sandbox-local</code>（+ native Landlock）</td></tr><tr><td><code>ctx.codeRuntime</code></td><td><code>code-runtime</code></td><td><code>code-runtime-worker</code>（Code Mode）</td></tr><tr><td><code>ctx.lsp</code></td><td><code>lsp</code></td><td><code>lsp-local</code></td></tr></tbody></table><blockquote><p>关键设计：<strong>fs 与 subprocess 提供方共享同一执行世界</strong>。把它们指向远程沙箱，Bash、PTY、LSP 一并搬走，无需提供方专用 fork。这是 seam 架构最漂亮的证明。</p></blockquote><h3 id="策略与交互" tabindex="-1">策略与交互 <a class="header-anchor" href="#策略与交互" aria-label="Permalink to &quot;策略与交互&quot;">​</a></h3><table tabindex="0"><thead><tr><th>服务</th><th>定义包</th><th>提供方实现</th></tr></thead><tbody><tr><td><code>ctx.approval</code></td><td><code>approval</code></td><td><code>acp</code>（自动化桥接）</td></tr><tr><td><code>ctx.permissionPresets</code></td><td><code>permission-presets</code></td><td>—（<code>workspace-write</code> / <code>danger-full-access</code>）</td></tr><tr><td><code>ctx.sandboxPolicy</code></td><td><code>sandbox-policy</code></td><td>—（统一部署默认模式与工作区根）</td></tr><tr><td><code>ctx.userQuestions</code></td><td><code>user-questions</code></td><td>UI 前端提供人工回答方</td></tr><tr><td><code>ctx.commands</code></td><td><code>commands</code></td><td>—（<code>/goal</code>、<code>/plan</code> 等人类命令）</td></tr><tr><td><code>ctx.planMode</code></td><td><code>plan-mode</code></td><td>—（已记录的计划状态）</td></tr></tbody></table><h3 id="上下文与技能" tabindex="-1">上下文与技能 <a class="header-anchor" href="#上下文与技能" aria-label="Permalink to &quot;上下文与技能&quot;">​</a></h3><table tabindex="0"><thead><tr><th>服务</th><th>定义包</th><th>提供方实现</th></tr></thead><tbody><tr><td><code>ctx.systemPrompt</code></td><td><code>system-prompt</code></td><td>—（片段组装注册表）</td></tr><tr><td><code>ctx.compaction</code></td><td><code>compaction</code></td><td><code>compaction-basic</code></td></tr><tr><td><code>ctx.spillStore</code></td><td><code>spill</code></td><td><code>spill-local</code></td></tr><tr><td><code>ctx.skills</code></td><td><code>skill</code></td><td><code>skill-filesystem</code>、<code>skill-badge</code></td></tr></tbody></table><h3 id="编排" tabindex="-1">编排 <a class="header-anchor" href="#编排" aria-label="Permalink to &quot;编排&quot;">​</a></h3><table tabindex="0"><thead><tr><th>服务</th><th>定义包</th><th>提供方实现</th></tr></thead><tbody><tr><td><code>ctx.subagents</code></td><td><code>subagent</code></td><td><code>-spawn-in-process</code>、<code>-fork-in-process</code>、<code>-acp</code>、<code>-codex</code>、<code>-claude-code</code>、<code>-dsh-sdk</code></td></tr><tr><td><code>ctx.workflowEngine</code></td><td><code>workflow</code></td><td><code>workflow-worker-thread</code></td></tr><tr><td><code>ctx.jobs</code></td><td><code>jobs</code></td><td><code>jobs-local</code></td></tr><tr><td><code>ctx.goals</code></td><td><code>goal</code></td><td>—</td></tr></tbody></table><h3 id="web-与外部接口" tabindex="-1">Web 与外部接口 <a class="header-anchor" href="#web-与外部接口" aria-label="Permalink to &quot;Web 与外部接口&quot;">​</a></h3><table tabindex="0"><thead><tr><th>服务</th><th>定义包</th><th>提供方实现</th></tr></thead><tbody><tr><td><code>ctx.web</code></td><td><code>web</code></td><td><code>web-search-exa/-perplexity/-deepseek</code>、<code>web-fetch-http</code></td></tr><tr><td><code>ctx.webServer</code></td><td><code>webserver</code></td><td>—（node:http 路由注册）</td></tr><tr><td><code>ctx.clientModules</code></td><td><code>modules</code></td><td>—（<code>__DSH_BOOT__</code> 客户端插件图）</td></tr><tr><td><code>ctx.apiProxy</code></td><td><code>apiproxy</code></td><td>—（传输无关的 Host 网关）</td></tr><tr><td><code>ctx.typert</code></td><td><code>typert-registry</code></td><td>—（运行时类型注册表）</td></tr><tr><td><code>ctx.typertGateway</code></td><td><code>api-gateway</code></td><td>—（RPC 调用网关）</td></tr></tbody></table><h2 id="_4-轮次流程-turn-flow" tabindex="-1">4. 轮次流程（Turn Flow） <a class="header-anchor" href="#_4-轮次流程-turn-flow" aria-label="Permalink to &quot;4. 轮次流程（Turn Flow）&quot;">​</a></h2><p>架构文档给出的权威描述：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>turn/start</span></span>
<span class="line"><span>  claim next-step input plus one queued message          ← 领取 inbox</span></span>
<span class="line"><span>  assemble prompt sections + tool schemas                ← 组装提示词</span></span>
<span class="line"><span>  -&gt; agent/pre-step          waterfall: reject | enter(messages)</span></span>
<span class="line"><span>     reject, 或首个 enter 被改写为空 → 关闭无步骤轮次</span></span>
<span class="line"><span>     step/start</span></span>
<span class="line"><span>     append entered messages as user/message             ← 写入日志</span></span>
<span class="line"><span>     derive model history from the log                   ← 从日志投影历史</span></span>
<span class="line"><span>     agent/request -&gt; llm/stream -&gt; assistant/chunk* -&gt; assistant/message</span></span>
<span class="line"><span>     tool/call* -&gt; tools/pre-execute -&gt; tools/execute -&gt; tools/post-execute -&gt; tool/result*</span></span>
<span class="line"><span>     step/end</span></span>
<span class="line"><span>     tools owe another request, or next-step input arrived -&gt; claim -&gt; next step</span></span>
<span class="line"><span>  -&gt; agent/turn-stopping        serial（无 next() 的终止检查点）</span></span>
<span class="line"><span>turn/end</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br></div></div><p>事件分类要点：</p><ul><li><strong>持久会话事件</strong>：<code>turn/*</code>、<code>step/*</code>、<code>user/message</code>、<code>assistant/*</code>、<code>tool/*</code></li><li><strong>实时扩展点</strong>（waterfall）：<code>agent/pre-step</code>、<code>agent/request</code>、<code>llm/stream</code>、<code>tools/pre-execute</code>、<code>tools/execute</code>、<code>tools/post-execute</code></li><li><strong>serial 终止检查点</strong>：<code>agent/turn-stopping</code>（无 <code>next()</code>，表示&quot;轮次即将停止&quot;）</li></ul><h3 id="inbox-输入如何到达驱动器" tabindex="-1">inbox：输入如何到达驱动器 <a class="header-anchor" href="#inbox-输入如何到达驱动器" aria-label="Permalink to &quot;inbox：输入如何到达驱动器&quot;">​</a></h3><p>输入通过同一个 <strong>inbox</strong> 到达驱动器：</p><ul><li>有些消息<strong>立即唤醒</strong>驱动器</li><li>注入的上下文（<code>agent.inject()</code>）<strong>留在 inbox 里</strong>，直到另一条消息将其唤醒——这就是&quot;steering 与注入上下文在后续认领批次经过同一 waterfall&quot;的机制</li><li><code>agent/pre-step</code> 决定模型看到什么：监听器可以改写已领取的消息，也可以<strong>直接拒绝</strong>它们；被拒绝的批次也会关闭一个<strong>无步骤的持久轮次</strong>，保证日志记录这次尝试</li></ul><h2 id="_5-能力-seam-的完整形态" tabindex="-1">5. 能力 seam 的完整形态 <a class="header-anchor" href="#_5-能力-seam-的完整形态" aria-label="Permalink to &quot;5. 能力 seam 的完整形态&quot;">​</a></h2><p>回顾三个角色，并补两个细节：</p><ul><li><strong>单一角色不是 seam</strong>。添加一项能力 = 同时设计 Service Definition、Provider、Consumer 三者</li><li><strong>一个包可合并多个角色</strong>：<code>dsh-llm</code> 同时承担 Service Definition 和 Consumer</li><li>seam 拥有自身 <code>ctx.&lt;key&gt;</code> 的 Service 必须是<strong>抽象类或具体注册表，绝不是 TS interface</strong>——因为它要承载生命周期与事件</li></ul><h2 id="_6-新行为放哪里-速查表" tabindex="-1">6. 新行为放哪里（速查表） <a class="header-anchor" href="#_6-新行为放哪里-速查表" aria-label="Permalink to &quot;6. 新行为放哪里（速查表）&quot;">​</a></h2><p>这是官方&quot;扩展点决策表&quot;的整理版，面试被问&quot;如果我想加 X 该怎么做&quot;时直接查：</p><table tabindex="0"><thead><tr><th>目标</th><th>机制</th></tr></thead><tbody><tr><td>添加模型提供方</td><td>在 <code>ctx.llm</code> 注册适配器</td></tr><tr><td>添加面向模型的能力</td><td>在 <code>ctx.tools</code> 注册；schema 加入提示词组装</td></tr><tr><td>让某个会话拥有不同能力集合</td><td>组装 agent preset；服务行需要 <code>isolate</code> realm</td></tr><tr><td>添加 shell 执行</td><td>注册 <code>ctx.shell</code> 后端；本地后端经 <code>ctx.subprocess</code> spawn</td></tr><tr><td>添加持久终端</td><td>注册 <code>ctx.terminals</code> 后端 + <code>dsh-tool-terminal</code></td></tr><tr><td>添加用户命令</td><td>在 <code>ctx.commands</code> 注册；无需模型轮次即可分派</td></tr><tr><td>添加后台工作</td><td>在 <code>ctx.jobs</code> 注册；<code>job_*</code> 工具收集/停止</td></tr><tr><td>添加文件系统访问或策略</td><td>注册 <code>ctx.fs</code> 提供方，或监听 <code>fs/*</code> 事件</td></tr><tr><td>限制所启动的进程</td><td>使用 <code>ctx.sandbox</code> 后端；消费方在 spawn 前包装 argv</td></tr><tr><td>拦截请求/工具/轮次</td><td>使用 <code>agent/*</code> 或 <code>tools/*</code> 事件</td></tr><tr><td>添加模型可见上下文</td><td>调用 <code>agent.inject()</code></td></tr><tr><td>添加 UI 集成</td><td>驱动 <code>ctx.agents</code> 并从 <code>session/event</code> 渲染</td></tr><tr><td>添加 Web Chat 节点</td><td>注册 <code>ConversationNodeDefinition</code> + keyed renderer</td></tr><tr><td>添加持久会话状态</td><td>扩展 <code>SessionEventMap</code>；从日志渲染和回放</td></tr><tr><td>fork 活跃会话</td><td><code>ctx.sessions.fork(source, boundary?, childSessionId?)</code></td></tr><tr><td>将注册项限定到单个 agent</td><td>使用该 agent 的 <code>agent.ctx</code></td></tr></tbody></table><h2 id="_7-心智图-三个平面" tabindex="-1">7. 心智图：三个平面 <a class="header-anchor" href="#_7-心智图-三个平面" aria-label="Permalink to &quot;7. 心智图：三个平面&quot;">​</a></h2><p>DSH 的全部逻辑可以压成三个平面：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>┌─────────────────────────────────────────────────────┐</span></span>
<span class="line"><span>│ 组合平面：profile + bundle + patch = 插件树（静态）      │</span></span>
<span class="line"><span>├─────────────────────────────────────────────────────┤</span></span>
<span class="line"><span>│ 运行平面：turn/step 状态机 + 事件瀑布（动态）            │</span></span>
<span class="line"><span>│   agent/*   实时协调（可拦截、不可回放）                 │</span></span>
<span class="line"><span>│   session/* 持久事实（可回放、不可改写）                 │</span></span>
<span class="line"><span>├─────────────────────────────────────────────────────┤</span></span>
<span class="line"><span>│ 能力平面：seam = Definition + Provider + Consumer      │</span></span>
<span class="line"><span>│   替换 Provider = 改变产品行为，Consumer 零改动          │</span></span>
<span class="line"><span>└─────────────────────────────────────────────────────┘</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br></div></div><p>下一篇进入<a href="/deep-dive/agent-loop">深度拆解 01：核心循环</a>，看驱动器如何把这套骨架跑起来。</p>`,51)])])}const u=e(a,[["render",c]]);export{b as __pageData,u as default};
